var a=[{id:"kaizen",nome:"Kaizen \u6539\u5584",origem:"Jap\xE3o \u2014 filosofia de melhoria cont\xEDnua da Toyota",resumo:"Pequenos passos todos os dias vencem maratonas de v\xE9spera. O site guarda sua sequ\xEAncia de dias e uma meta di\xE1ria pequena e alcan\xE7\xE1vel.",comoUsar:"Defina uma meta di\xE1ria modesta (ex.: 30 atividades). N\xE3o quebre a sequ\xEAncia \u2014 15 minutos j\xE1 contam.",onde:{rotulo:"Ver meta do dia",link:"/"}},{id:"shuhari",nome:"Shu-Ha-Ri \u5B88\u7834\u96E2",origem:"Jap\xE3o \u2014 artes marciais e cerim\xF4nia do ch\xE1",resumo:"Shu: obedecer \xE0 forma (decorar a letra da lei). Ha: quebrar a forma (entender exce\xE7\xF5es e pegadinhas). Ri: transcender (explicar com suas palavras e acertar quest\xF5es dif\xEDceis).",comoUsar:"Cada mat\xE9ria mostra seu est\xE1gio. Os treinos sobem de faixa branca para faixa preta conforme voc\xEA acerta.",onde:{rotulo:"Escolher mat\xE9ria",link:"/"}},{id:"leitner",nome:"Repeti\xE7\xE3o espa\xE7ada (caixas de Leitner)",origem:"Alemanha \u2014 Ebbinghaus (curva do esquecimento) e Sebastian Leitner",resumo:"Voc\xEA rev\xEA um cart\xE3o logo antes de esquec\xEA-lo. Acertou: ele vai para uma caixa com intervalo maior (0, 1, 3, 7, 15 dias). Errou: volta para a caixa 1.",comoUsar:'Abra a Revis\xE3o do Dia todos os dias. Seja honesto ao marcar "Sabia" ou "N\xE3o sabia".',onde:{rotulo:"Abrir revis\xE3o",link:"/revisao"}},{id:"kumon",nome:"M\xE9todo Kumon \u516C\u6587",origem:"Jap\xE3o \u2014 Toru Kumon, 1954",resumo:"Exerc\xEDcios em degraus: s\xF3 se avan\xE7a quando o n\xEDvel atual est\xE1 dominado. Aqui, as quest\xF5es est\xE3o em faixas \u2014 branca, verde e preta.",comoUsar:"No Treino, comece pela faixa branca. Com 80% de acerto, suba de faixa.",onde:{rotulo:"Treinar quest\xF5es",link:"/simulado"}},{id:"escriba",nome:"Escriba eg\xEDpcio \u{13080}",origem:"Egito Antigo \u2014 escribas memorizavam copiando textos de mem\xF3ria",resumo:"Os escribas aprendiam reescrevendo os textos sagrados. Recordar e escrever (evoca\xE7\xE3o ativa) fixa muito mais do que reler.",comoUsar:"Na aba Escriba de cada mat\xE9ria, complete os artigos de lei digitando as palavras que faltam.",onde:{rotulo:"Escolher mat\xE9ria",link:"/"}},{id:"palacio",nome:"Pal\xE1cio da Mem\xF3ria (m\xE9todo de loci)",origem:"Gr\xE9cia Antiga \u2014 Sim\xF4nides de Ceos; usado tamb\xE9m por oradores romanos",resumo:'Associe cada fato a um lugar que voc\xEA conhece e a uma cena absurda. Para lembrar, "caminhe" pelos c\xF4modos. Aqui o pal\xE1cio \xE9 a pr\xF3pria C\xE2mara de Cuiab\xE1.',comoUsar:"Na aba Pal\xE1cio, percorra os lugares e feche os olhos imaginando cada cena antes de virar o cart\xE3o.",onde:{rotulo:"Escolher mat\xE9ria",link:"/"}},{id:"freire",nome:"Pedagogia de Paulo Freire",origem:'Brasil \u2014 Paulo Freire, "Pedagogia do Oprimido"',resumo:'Aprende-se a partir da realidade de quem estuda. As li\xE7\xF5es trazem o bloco "Na vida real", ligando a lei ao dia a dia da C\xE2mara e de Cuiab\xE1.',comoUsar:'Ao ler cada li\xE7\xE3o, pergunte: "onde isso aparece no trabalho da C\xE2mara?".',onde:{rotulo:"Escolher mat\xE9ria",link:"/"}},{id:"macete",nome:"Macetes de concurseiro",origem:"Brasil \u2014 tradi\xE7\xE3o dos cursinhos (LIMPE, siglas, rimas)",resumo:"Siglas, frases e rimas transformam listas em algo pronunci\xE1vel. O c\xE9rebro guarda melhor o que \xE9 engra\xE7ado ou r\xEDtmico.",comoUsar:"Leia o macete em voz alta 3 vezes e depois crie o seu pr\xF3prio.",onde:{rotulo:"Escolher mat\xE9ria",link:"/"}},{id:"feynman",nome:"T\xE9cnica Feynman",origem:"EUA \u2014 Richard Feynman, f\xEDsico, Nobel de 1965",resumo:'Se voc\xEA n\xE3o consegue explicar de forma simples, ainda n\xE3o entendeu. As li\xE7\xF5es trazem uma "explica\xE7\xE3o para crian\xE7a".',comoUsar:"Feche a li\xE7\xE3o e explique o tema em voz alta, como se fosse para algu\xE9m de 12 anos. Onde travar, volte e releia.",onde:{rotulo:"Escolher mat\xE9ria",link:"/"}},{id:"pomodoro",nome:"Pomodoro",origem:"It\xE1lia \u2014 Francesco Cirillo, anos 1980",resumo:"25 minutos de foco total, 5 de pausa. Depois de 4 ciclos, uma pausa longa.",comoUsar:"Use o cron\xF4metro do topo da p\xE1gina. Durante o foco, s\xF3 uma mat\xE9ria e celular longe.",onde:{rotulo:"Abrir foco",link:"/foco"}},{id:"kanban",nome:"Kanban \u770B\u677F",origem:"Jap\xE3o \u2014 sistema de cart\xF5es da Toyota",resumo:'Visualize o trabalho: A estudar \u2192 Estudando \u2192 Revisando \u2192 Dominado. Limite o que est\xE1 "em andamento" para n\xE3o se dispersar.',comoUsar:'Mova as li\xE7\xF5es pelo quadro. Tente manter no m\xE1ximo 3 em "Estudando".',onde:{rotulo:"Abrir quadro",link:"/kanban"}},{id:"hansei",nome:"Hansei \u53CD\u7701",origem:"Jap\xE3o \u2014 pr\xE1tica de autorreflex\xE3o",resumo:"Ao fim do dia, reflita: o que aprendi? Onde errei? O que farei diferente amanh\xE3? A reflex\xE3o transforma erro em aprendizado.",comoUsar:"Escreva 2 ou 3 linhas no di\xE1rio de reflex\xE3o da p\xE1gina Foco.",onde:{rotulo:"Escrever reflex\xE3o",link:"/foco"}},{id:"podcast",nome:"Aprendizagem auditiva (podcast)",origem:"Gr\xE9cia e \xC1frica \u2014 tradi\xE7\xE3o oral; hoje, os podcasts de estudo",resumo:"Antes da escrita, o conhecimento passava de boca em boca. Ouvir a mat\xE9ria em forma de conversa aproveita tempo morto (\xF4nibus, academia) e a pausa da pergunta-rel\xE2mpago for\xE7a a recorda\xE7\xE3o ativa.",comoUsar:"Monte um epis\xF3dio com as li\xE7\xF5es da semana e ou\xE7a no trajeto. Na pausa, responda em voz alta antes da resposta.",onde:{rotulo:"Montar podcast",link:"/podcast"}},{id:"socratico",nome:"M\xE9todo socr\xE1tico (Sensei)",origem:"Gr\xE9cia Antiga \u2014 S\xF3crates ensinava fazendo perguntas",resumo:"S\xF3crates n\xE3o dava respostas prontas: perguntava at\xE9 o aluno chegar l\xE1. O Sensei faz sabatinas, corrige e explica; voc\xEA tamb\xE9m pode tirar d\xFAvidas falando pelo microfone.",comoUsar:"Use a Sabatina depois de estudar uma mat\xE9ria. Responda com suas palavras, sem olhar a li\xE7\xE3o.",onde:{rotulo:"Conversar com o Sensei",link:"/sensei"}}];export{a};
